319	void KeeperStorage::UncommittedState::commit(int64_t commit_zxid)
320	{
321	    assert(deltas.empty() || deltas.front().zxid >= commit_zxid);
322	
323	    while (!deltas.empty() && deltas.front().zxid == commit_zxid)
324	    {
325	        if (std::holds_alternative<SubDeltaEnd>(deltas.front().operation))
326	        {
327	            deltas.pop_front();
328	            break;
329	        }
330	
331	        deltas.pop_front();
332	    }
333	
334	    // delete all cached nodes that were not modified after the commit_zxid
335	    // the commit can end on SubDeltaEnd so we don't want to clear cached nodes too soon
336	    if (deltas.empty() || deltas.front().zxid > commit_zxid)
337	        std::erase_if(nodes, [commit_zxid](const auto & node) { return node.second.zxid == commit_zxid; });
338	}
