340	void KeeperStorage::UncommittedState::rollback(int64_t rollback_zxid)
341	{
342	    // we can only rollback the last zxid (if there is any)
343	    // if there is a delta with a larger zxid, we have invalid state
344	    if (!deltas.empty() && deltas.back().zxid > rollback_zxid)
345	        throw DB::Exception(
346	            DB::ErrorCodes::LOGICAL_ERROR,
347	            "Invalid state of deltas found while trying to rollback request. Last ZXID ({}) is larger than the requested ZXID ({})",
348	            deltas.back().zxid,
349	            rollback_zxid);
350	
351	    // we need to undo ephemeral mapping modifications
352	    // CreateNodeDelta added ephemeral for session id -> we need to remove it
353	    // RemoveNodeDelta removed ephemeral for session id -> we need to add it back
354	    for (auto delta_it = deltas.rbegin(); delta_it != deltas.rend(); ++delta_it)
355	    {
356	        if (delta_it->zxid < rollback_zxid)
357	            break;
358	
359	        assert(delta_it->zxid == rollback_zxid);
360	        if (!delta_it->path.empty())
361	        {
362	            std::visit(
363	                [&]<typename DeltaType>(const DeltaType & operation)
364	                {
365	                    if constexpr (std::same_as<DeltaType, CreateNodeDelta>)
366	                    {
367	                        if (operation.stat.ephemeralOwner != 0)
368	                            storage.unregisterEphemeralPath(operation.stat.ephemeralOwner, delta_it->path);
369	                    }
370	                    else if constexpr (std::same_as<DeltaType, RemoveNodeDelta>)
371	                    {
372	                        if (operation.ephemeral_owner != 0)
373	                            storage.ephemerals[operation.ephemeral_owner].emplace(delta_it->path);
374	                    }
375	                },
376	                delta_it->operation);
377	        }
378	    }
379	
380	    std::erase_if(deltas, [rollback_zxid](const auto & delta) { return delta.zxid == rollback_zxid; });
381	
382	    std::unordered_set<std::string> deleted_nodes;
383	    std::erase_if(
384	        nodes,
385	        [&, rollback_zxid](const auto & node)
386	        {
387	            if (node.second.zxid == rollback_zxid)
388	            {
389	                deleted_nodes.emplace(node.first);
390	                return true;
391	            }
392	            return false;
393	        });
394	
395	    // recalculate all the uncommitted deleted nodes
396	    for (const auto & delta : deltas)
397	    {
398	        if (!delta.path.empty() && deleted_nodes.contains(delta.path))
399	            applyDelta(delta);
400	    }
401	}
