438	    // Deltas are added with increasing ZXIDs
439	    // If there are no deltas for the commit_zxid (e.g. read requests), we instantly return
440	    // on first delta
441	    for (auto & delta : uncommitted_state.deltas)
442	    {
443	        if (delta.zxid > commit_zxid)
444	            break;
445	
446	        bool finish_subdelta = false;
447	        auto result = std::visit(
448	            [&, &path = delta.path]<typename DeltaType>(DeltaType & operation) -> Coordination::Error
449	            {
450	                if constexpr (std::same_as<DeltaType, KeeperStorage::CreateNodeDelta>)
451	                {
452	                    if (!createNode(
