454	                            std::move(operation.data),
455	                            operation.stat,
456	                            operation.is_sequental,
457	                            std::move(operation.acls)))
458	                        onStorageInconsistency();
459	
460	                    return Coordination::Error::ZOK;
461	                }
462	                else if constexpr (std::same_as<DeltaType, KeeperStorage::UpdateNodeDelta>)
463	                {
464	                    auto node_it = container.find(path);
465	                    if (node_it == container.end())
466	                        onStorageInconsistency();
467	
468	                    if (operation.version != -1 && operation.version != node_it->value.stat.version)
469	                        onStorageInconsistency();
