473	                    addDigest(updated_node->value, path);
474	
475	                    return Coordination::Error::ZOK;
476	                }
477	                else if constexpr (std::same_as<DeltaType, KeeperStorage::RemoveNodeDelta>)
478	                {
479	                    if (!removeNode(path, operation.version))
480	                        onStorageInconsistency();
481	
482	                    return Coordination::Error::ZOK;
483	                }
484	                else if constexpr (std::same_as<DeltaType, KeeperStorage::SetACLDelta>)
485	                {
486	                    auto node_it = container.find(path);
487	                    if (node_it == container.end())
488	                        onStorageInconsistency();
